00129   class Rom
00130   {
00131   public:
00132     Rom() : m_scansInitialized(false) {}
00133     ~Rom() { xUninitScanArrays(); }
00134     void                init        ()                       { xInitScanArrays(); }
00135     const NbInfoSbb*    getNbInfoSbb( int hd, int vd ) const { return m_scanId2NbInfoSbbArray[hd][vd]; }
00136     const NbInfoOut*    getNbInfoOut( int hd, int vd ) const { return m_scanId2NbInfoOutArray[hd][vd]; }
00137     const TUParameters* getTUPars   ( const CompArea& area, const ComponentID compID ) const
00138     {
00139       return m_tuParameters[floorLog2(area.width)][floorLog2(area.height)][toChannelType(compID)];
00140     }
00141   private:
00142     void  xInitScanArrays   ();
00143     void  xUninitScanArrays ();
00144   private:
00145     bool          m_scansInitialized;
00146     NbInfoSbb*    m_scanId2NbInfoSbbArray[ MAX_CU_DEPTH+1 ][ MAX_CU_DEPTH+1 ];
00147     NbInfoOut*    m_scanId2NbInfoOutArray[ MAX_CU_DEPTH+1 ][ MAX_CU_DEPTH+1 ];
00148     TUParameters* m_tuParameters         [ MAX_CU_DEPTH+1 ][ MAX_CU_DEPTH+1 ][ MAX_NUM_CHANNEL_TYPE ];
00149   };
00150 
00151   void Rom::xInitScanArrays()
00152   {
00153     if( m_scansInitialized )
00154     {
00155       return;
00156     }
00157     ::memset( m_scanId2NbInfoSbbArray, 0, sizeof(m_scanId2NbInfoSbbArray) );
00158     ::memset( m_scanId2NbInfoOutArray, 0, sizeof(m_scanId2NbInfoOutArray) );
00159     ::memset( m_tuParameters,          0, sizeof(m_tuParameters) );
00160 
00161     uint32_t raster2id[ MAX_CU_SIZE * MAX_CU_SIZE ];
00162     ::memset(raster2id, 0, sizeof(raster2id));
00163 
00164     for( int hd = 0; hd <= MAX_CU_DEPTH; hd++ )
00165     {
00166       for( int vd = 0; vd <= MAX_CU_DEPTH; vd++ )
00167       {
00168         if( (hd == 0 && vd <= 1) || (hd <= 1 && vd == 0) )
00169         {
00170           continue;
00171         }
00172         const uint32_t      blockWidth    = (1 << hd);
00173         const uint32_t      blockHeight   = (1 << vd);
00174         const uint32_t      log2CGWidth   = g_log2SbbSize[hd][vd][0];
00175         const uint32_t      log2CGHeight  = g_log2SbbSize[hd][vd][1];
00176         const uint32_t      groupWidth    = 1 << log2CGWidth;
00177         const uint32_t      groupHeight   = 1 << log2CGHeight;
00178         const uint32_t      groupSize     = groupWidth * groupHeight;
00179         const CoeffScanType scanType      = SCAN_DIAG;
00180         const SizeType      blkWidthIdx   = gp_sizeIdxInfo->idxFrom( blockWidth  );
00181         const SizeType      blkHeightIdx  = gp_sizeIdxInfo->idxFrom( blockHeight );
00182         const ScanElement * scanId2RP     = g_scanOrder[SCAN_GROUPED_4x4][scanType][blkWidthIdx][blkHeightIdx];
00183         NbInfoSbb*&         sId2NbSbb     = m_scanId2NbInfoSbbArray[hd][vd];
00184         NbInfoOut*&         sId2NbOut     = m_scanId2NbInfoOutArray[hd][vd];
00185         // consider only non-zero-out region
00186         const uint32_t      blkWidthNZOut = std::min<unsigned>( JVET_C0024_ZERO_OUT_TH, blockWidth  );
00187         const uint32_t      blkHeightNZOut= std::min<unsigned>( JVET_C0024_ZERO_OUT_TH, blockHeight );
00188         const uint32_t      totalValues   = blkWidthNZOut * blkHeightNZOut;
00189 
00190         sId2NbSbb = new NbInfoSbb[ totalValues ];
00191         sId2NbOut = new NbInfoOut[ totalValues ];
00192 
00193         for( uint32_t scanId = 0; scanId < totalValues; scanId++ )
00194         {
00195           raster2id[scanId2RP[scanId].idx] = scanId;
00196         }
00197 
00198         for( unsigned scanId = 0; scanId < totalValues; scanId++ )
00199         {
00200           const int posX = scanId2RP[scanId].x;
00201           const int posY = scanId2RP[scanId].y;
00202           const int rpos = scanId2RP[scanId].idx;
00203           {
00204             //===== inside subband neighbours =====
00205             NbInfoSbb&     nbSbb  = sId2NbSbb[ scanId ];
00206             const int      begSbb = scanId - ( scanId & (groupSize-1) ); // first pos in current subblock
00207             int            cpos[5];
00208 
00209             cpos[0] = ( posX + 1 < blkWidthNZOut                              ? ( raster2id[rpos+1           ] < groupSize + begSbb ? raster2id[rpos+1           ] - begSbb : 0 ) : 0 );
00210             cpos[1] = ( posX + 2 < blkWidthNZOut                              ? ( raster2id[rpos+2           ] < groupSize + begSbb ? raster2id[rpos+2           ] - begSbb : 0 ) : 0 );
00211             cpos[2] = ( posX + 1 < blkWidthNZOut && posY + 1 < blkHeightNZOut ? ( raster2id[rpos+1+blockWidth] < groupSize + begSbb ? raster2id[rpos+1+blockWidth] - begSbb : 0 ) : 0 );
00212             cpos[3] = ( posY + 1 < blkHeightNZOut                             ? ( raster2id[rpos+  blockWidth] < groupSize + begSbb ? raster2id[rpos+  blockWidth] - begSbb : 0 ) : 0 );
00213             cpos[4] = ( posY + 2 < blkHeightNZOut                             ? ( raster2id[rpos+2*blockWidth] < groupSize + begSbb ? raster2id[rpos+2*blockWidth] - begSbb : 0 ) : 0 );
00214 
00215             for( nbSbb.num = 0; true; )
00216             {
00217               int nk = -1;
00218               for( int k = 0; k < 5; k++ )
00219               {
00220                 if( cpos[k] != 0 && ( nk < 0 || cpos[k] < cpos[nk] ) )
00221                 {
00222                   nk = k;
00223                 }
00224               }
00225               if( nk < 0 )
00226               {
00227                 break;
00228               }
00229               nbSbb.inPos[ nbSbb.num++ ] = uint8_t( cpos[nk] );
00230               cpos[nk] = 0;
00231             }
00232             for( int k = nbSbb.num; k < 5; k++ )
00233             {
00234               nbSbb.inPos[k] = 0;
00235             }
00236           }
00237           {
00238             //===== outside subband neighbours =====
00239             NbInfoOut&     nbOut  = sId2NbOut[ scanId ];
00240             const int      begSbb = scanId - ( scanId & (groupSize-1) ); // first pos in current subblock
00241             int            cpos[5];
00242 
00243             cpos[0] = ( posX + 1 < blkWidthNZOut                              ? ( raster2id[rpos+1           ] >= groupSize + begSbb ? raster2id[rpos+1           ] : 0 ) : 0 );
00244             cpos[1] = ( posX + 2 < blkWidthNZOut                              ? ( raster2id[rpos+2           ] >= groupSize + begSbb ? raster2id[rpos+2           ] : 0 ) : 0 );
00245             cpos[2] = ( posX + 1 < blkWidthNZOut && posY + 1 < blkHeightNZOut ? ( raster2id[rpos+1+blockWidth] >= groupSize + begSbb ? raster2id[rpos+1+blockWidth] : 0 ) : 0 );
00246             cpos[3] = ( posY + 1 < blkHeightNZOut                             ? ( raster2id[rpos+  blockWidth] >= groupSize + begSbb ? raster2id[rpos+  blockWidth] : 0 ) : 0 );
00247             cpos[4] = ( posY + 2 < blkHeightNZOut                             ? ( raster2id[rpos+2*blockWidth] >= groupSize + begSbb ? raster2id[rpos+2*blockWidth] : 0 ) : 0 );
00248 
00249             for( nbOut.num = 0; true; )
00250             {
00251               int nk = -1;
00252               for( int k = 0; k < 5; k++ )
00253               {
00254                 if( cpos[k] != 0 && ( nk < 0 || cpos[k] < cpos[nk] ) )
00255                 {
00256                   nk = k;
00257                 }
00258               }
00259               if( nk < 0 )
00260               {
00261                 break;
00262               }
00263               nbOut.outPos[ nbOut.num++ ] = uint16_t( cpos[nk] );
00264               cpos[nk] = 0;
00265             }
00266             for( int k = nbOut.num; k < 5; k++ )
00267             {
00268               nbOut.outPos[k] = 0;
00269             }
00270             nbOut.maxDist = ( scanId == 0 ? 0 : sId2NbOut[scanId-1].maxDist );
00271             for( int k = 0; k < nbOut.num; k++ )
00272             {
00273               if( nbOut.outPos[k] > nbOut.maxDist )
00274               {
00275                 nbOut.maxDist = nbOut.outPos[k];
00276               }
00277             }
00278           }
00279         }
00280 
00281         // make it relative
00282         for( unsigned scanId = 0; scanId < totalValues; scanId++ )
00283         {
00284           NbInfoOut& nbOut  = sId2NbOut[scanId];
00285           const int  begSbb = scanId - ( scanId & (groupSize-1) ); // first pos in current subblock
00286           for( int k = 0; k < nbOut.num; k++ )
00287           {
00288             CHECK(begSbb > nbOut.outPos[k], "Position must be past sub block begin");
00289             nbOut.outPos[k] -= begSbb;
00290           }
00291           nbOut.maxDist -= scanId;
00292         }
00293 
00294         for( int chId = 0; chId < MAX_NUM_CHANNEL_TYPE; chId++ )
00295         {
00296           m_tuParameters[hd][vd][chId] = new TUParameters( *this, blockWidth, blockHeight, ChannelType(chId) );
00297         }
00298       }
00299     }
00300     m_scansInitialized = true;
00301   }
00302 
00303   void Rom::xUninitScanArrays()
00304   {
00305     if( !m_scansInitialized )
00306     {
00307       return;
00308     }
00309     for( int hd = 0; hd <= MAX_CU_DEPTH; hd++ )
00310     {
00311       for( int vd = 0; vd <= MAX_CU_DEPTH; vd++ )
00312       {
00313         NbInfoSbb*& sId2NbSbb = m_scanId2NbInfoSbbArray[hd][vd];
00314         NbInfoOut*& sId2NbOut = m_scanId2NbInfoOutArray[hd][vd];
00315         if( sId2NbSbb )
00316         {
00317           delete [] sId2NbSbb;
00318         }
00319         if( sId2NbOut )
00320         {
00321           delete [] sId2NbOut;
00322         }
00323         for( int chId = 0; chId < MAX_NUM_CHANNEL_TYPE; chId++ )
00324         {
00325           TUParameters*& tuPars = m_tuParameters[hd][vd][chId];
00326           if( tuPars )
00327           {
00328             delete tuPars;
00329           }
00330         }
00331       }
00332     }
00333     m_scansInitialized = false;
00334   }
00335 
