00339 
00340   TUParameters::TUParameters( const Rom& rom, const unsigned width, const unsigned height, const ChannelType chType )
00341   {
00342     m_chType              = chType;
00343     m_width               = width;
00344     m_height              = height;
00345     const uint32_t nonzeroWidth  = std::min<uint32_t>(JVET_C0024_ZERO_OUT_TH, m_width);
00346     const uint32_t nonzeroHeight = std::min<uint32_t>(JVET_C0024_ZERO_OUT_TH, m_height);
00347     m_numCoeff                   = nonzeroWidth * nonzeroHeight;
00348     const int log2W       = floorLog2( m_width  );
00349     const int log2H       = floorLog2( m_height );
00350     m_log2SbbWidth        = g_log2SbbSize[ log2W ][ log2H ][0];
00351     m_log2SbbHeight       = g_log2SbbSize[ log2W ][ log2H ][1];
00352     m_log2SbbSize         = m_log2SbbWidth + m_log2SbbHeight;
00353     m_sbbSize             = ( 1 << m_log2SbbSize );
00354     m_sbbMask             = m_sbbSize - 1;
00355     m_widthInSbb  = nonzeroWidth >> m_log2SbbWidth;
00356     m_heightInSbb = nonzeroHeight >> m_log2SbbHeight;
00357     m_numSbb              = m_widthInSbb * m_heightInSbb;
00358     m_scanType            = SCAN_DIAG;
00359     SizeType        hsbb  = gp_sizeIdxInfo->idxFrom( m_widthInSbb  );
00360     SizeType        vsbb  = gp_sizeIdxInfo->idxFrom( m_heightInSbb );
00361     SizeType        hsId  = gp_sizeIdxInfo->idxFrom( m_width  );
00362     SizeType        vsId  = gp_sizeIdxInfo->idxFrom( m_height );
00363     m_scanSbbId2SbbPos    = g_scanOrder     [ SCAN_UNGROUPED   ][ m_scanType ][ hsbb ][ vsbb ];
00364     m_scanId2BlkPos       = g_scanOrder     [ SCAN_GROUPED_4x4 ][ m_scanType ][ hsId ][ vsId ];
00365     m_scanId2NbInfoSbb    = rom.getNbInfoSbb( log2W, log2H );
00366     m_scanId2NbInfoOut    = rom.getNbInfoOut( log2W, log2H );
00367     m_scanInfo            = new ScanInfo[ m_numCoeff ];
00368     for( int scanIdx = 0; scanIdx < m_numCoeff; scanIdx++ )
00369     {
00370       xSetScanInfo( m_scanInfo[scanIdx], scanIdx );
00371     }
00372   }
00373 
00374 
00375   void TUParameters::xSetScanInfo( ScanInfo& scanInfo, int scanIdx )
00376   {
00377     scanInfo.chType     = m_chType;
00378     scanInfo.tuWidth    = m_width;
00379     scanInfo.tuHeight   = m_height;
00380     scanInfo.sbbSize    = m_sbbSize;
00381     scanInfo.numSbb     = m_numSbb;
00382     scanInfo.scanIdx    = scanIdx;
00383     scanInfo.rasterPos  = m_scanId2BlkPos[scanIdx].idx;
00384     scanInfo.sbbPos     = m_scanSbbId2SbbPos[scanIdx >> m_log2SbbSize].idx;
00385     scanInfo.insidePos  = scanIdx & m_sbbMask;
00386     scanInfo.eosbb      = ( scanInfo.insidePos == 0 );
00387     scanInfo.spt        = SCAN_ISCSBB;
00388     if(  scanInfo.insidePos == m_sbbMask && scanIdx > scanInfo.sbbSize && scanIdx < m_numCoeff - 1 )
00389       scanInfo.spt      = SCAN_SOCSBB;
00390     else if( scanInfo.eosbb && scanIdx > 0 && scanIdx < m_numCoeff - m_sbbSize )
00391       scanInfo.spt      = SCAN_EOCSBB;
00392     scanInfo.posX = m_scanId2BlkPos[scanIdx].x;
00393     scanInfo.posY = m_scanId2BlkPos[scanIdx].y;
00394     if( scanIdx )
00395     {
00396       const int nextScanIdx = scanIdx - 1;
00397       const int diag        = m_scanId2BlkPos[nextScanIdx].x + m_scanId2BlkPos[nextScanIdx].y;
00398       if( m_chType == CHANNEL_TYPE_LUMA )
00399       {
00400         scanInfo.sigCtxOffsetNext = ( diag < 2 ? 8 : diag < 5 ?  4 : 0 );
00401         scanInfo.gtxCtxOffsetNext = ( diag < 1 ? 16 : diag < 3 ? 11 : diag < 10 ? 6 : 1 );
00402       }
00403       else
00404       {
00405         scanInfo.sigCtxOffsetNext = ( diag < 2 ? 4 : 0 );
00406         scanInfo.gtxCtxOffsetNext = ( diag < 1 ? 6 : 1 );
00407       }
00408       scanInfo.nextInsidePos      = nextScanIdx & m_sbbMask;
00409       scanInfo.nextNbInfoSbb      = m_scanId2NbInfoSbb[ nextScanIdx ];
00410       if( scanInfo.eosbb )
00411       {
00412         const int nextSbbPos  = m_scanSbbId2SbbPos[nextScanIdx >> m_log2SbbSize].idx;
00413         const int nextSbbPosY = nextSbbPos               / m_widthInSbb;
00414         const int nextSbbPosX = nextSbbPos - nextSbbPosY * m_widthInSbb;
00415         scanInfo.nextSbbRight = ( nextSbbPosX < m_widthInSbb  - 1 ? nextSbbPos + 1            : 0 );
00416         scanInfo.nextSbbBelow = ( nextSbbPosY < m_heightInSbb - 1 ? nextSbbPos + m_widthInSbb : 0 );
00417       }
00418     }
00419   }
