00423   class RateEstimator
00424   {
00425   public:
00426     RateEstimator () {}
00427     ~RateEstimator() {}
00428     void initCtx  ( const TUParameters& tuPars, const TransformUnit& tu, const ComponentID compID, const FracBitsAccess& fracBitsAccess );
00429 
00430     inline const BinFracBits *sigSbbFracBits() const { return m_sigSbbFracBits; }
00431     inline const BinFracBits *sigFlagBits(unsigned stateId) const
00432     {
00433       return m_sigFracBits[std::max(((int) stateId) - 1, 0)];
00434     }
00435     inline const CoeffFracBits *gtxFracBits(unsigned stateId) const { return m_gtxFracBits; }
00436     inline int32_t              lastOffset(unsigned scanIdx) const
00437     {
00438       return m_lastBitsX[m_scanId2Pos[scanIdx].x] + m_lastBitsY[m_scanId2Pos[scanIdx].y];
00439     }
00440 
00441   private:
00442     void  xSetLastCoeffOffset ( const FracBitsAccess& fracBitsAccess, const TUParameters& tuPars, const TransformUnit& tu, const ComponentID compID );
00443     void  xSetSigSbbFracBits  ( const FracBitsAccess& fracBitsAccess, ChannelType chType );
00444     void  xSetSigFlagBits     ( const FracBitsAccess& fracBitsAccess, ChannelType chType );
00445     void  xSetGtxFlagBits     ( const FracBitsAccess& fracBitsAccess, ChannelType chType );
00446 
00447   private:
00448     static const unsigned sm_numCtxSetsSig    = 3;
00449     static const unsigned sm_numCtxSetsGtx    = 2;
00450     static const unsigned sm_maxNumSigSbbCtx  = 2;
00451     static const unsigned sm_maxNumSigCtx     = 12;
00452     static const unsigned sm_maxNumGtxCtx     = 21;
00453 
00454   private:
00455     const ScanElement * m_scanId2Pos;
00456     int32_t             m_lastBitsX      [ MAX_TB_SIZEY ];
00457     int32_t             m_lastBitsY      [ MAX_TB_SIZEY ];
00458     BinFracBits         m_sigSbbFracBits [ sm_maxNumSigSbbCtx ];
00459     BinFracBits         m_sigFracBits    [ sm_numCtxSetsSig   ][ sm_maxNumSigCtx ];
00460     CoeffFracBits       m_gtxFracBits                          [ sm_maxNumGtxCtx ];
00461   };
00462 
00463   void RateEstimator::initCtx( const TUParameters& tuPars, const TransformUnit& tu, const ComponentID compID, const FracBitsAccess& fracBitsAccess )
00464   {
00465     m_scanId2Pos = tuPars.m_scanId2BlkPos;
00466     xSetSigSbbFracBits  ( fracBitsAccess, tuPars.m_chType );
00467     xSetSigFlagBits     ( fracBitsAccess, tuPars.m_chType );
00468     xSetGtxFlagBits     ( fracBitsAccess, tuPars.m_chType );
00469     xSetLastCoeffOffset ( fracBitsAccess, tuPars, tu, compID );
00470   }
00471 
00472   void RateEstimator::xSetLastCoeffOffset( const FracBitsAccess& fracBitsAccess, const TUParameters& tuPars, const TransformUnit& tu, const ComponentID compID )
00473   {
00474     const ChannelType chType = ( compID == COMPONENT_Y ? CHANNEL_TYPE_LUMA : CHANNEL_TYPE_CHROMA );
00475     int32_t cbfDeltaBits = 0;
00476     if( compID == COMPONENT_Y && !CU::isIntra(*tu.cu) && !tu.depth )
00477     {
00478       const BinFracBits bits  = fracBitsAccess.getFracBitsArray( Ctx::QtRootCbf() );
00479       cbfDeltaBits            = int32_t( bits.intBits[1] ) - int32_t( bits.intBits[0] );
00480     }
00481     else
00482     {
00483       BinFracBits bits;
00484       bool prevLumaCbf           = false;
00485       bool lastCbfIsInferred     = false;
00486       bool useIntraSubPartitions = tu.cu->ispMode && isLuma(chType);
00487       if( useIntraSubPartitions )
00488       {
00489         bool rootCbfSoFar = false;
00490         bool isLastSubPartition = CU::isISPLast(*tu.cu, tu.Y(), compID);
00491         uint32_t nTus = tu.cu->ispMode == HOR_INTRA_SUBPARTITIONS ? tu.cu->lheight() >> floorLog2(tu.lheight()) : tu.cu->lwidth() >> floorLog2(tu.lwidth());
00492         if( isLastSubPartition )
00493         {
00494           TransformUnit* tuPointer = tu.cu->firstTU;
00495           for( int tuIdx = 0; tuIdx < nTus - 1; tuIdx++ )
00496           {
00497             rootCbfSoFar |= TU::getCbfAtDepth(*tuPointer, COMPONENT_Y, tu.depth);
00498             tuPointer     = tuPointer->next;
00499           }
00500           if( !rootCbfSoFar )
00501           {
00502             lastCbfIsInferred = true;
00503           }
00504         }
00505         if( !lastCbfIsInferred )
00506         {
00507           prevLumaCbf = TU::getPrevTuCbfAtDepth(tu, compID, tu.depth);
00508         }
00509         bits = fracBitsAccess.getFracBitsArray(Ctx::QtCbf[compID](DeriveCtx::CtxQtCbf(compID, prevLumaCbf, true)));
00510       }
00511       else
00512       {
00513         bits = fracBitsAccess.getFracBitsArray(Ctx::QtCbf[compID](DeriveCtx::CtxQtCbf(compID, tu.cbf[COMPONENT_Cb])));
00514       }
00515       cbfDeltaBits = lastCbfIsInferred ? 0 : int32_t(bits.intBits[1]) - int32_t(bits.intBits[0]);
00516     }
00517 
00518     static const unsigned prefixCtx[] = { 0, 0, 0, 3, 6, 10, 15, 21 };
00519     uint32_t              ctxBits  [ LAST_SIGNIFICANT_GROUPS ];
00520     for( unsigned xy = 0; xy < 2; xy++ )
00521     {
00522       int32_t             bitOffset   = ( xy ? cbfDeltaBits : 0 );
00523       int32_t*            lastBits    = ( xy ? m_lastBitsY : m_lastBitsX );
00524       const unsigned      size        = ( xy ? tuPars.m_height : tuPars.m_width );
00525       const unsigned      log2Size    = ceilLog2( size );
00526       const bool          useYCtx     = ( xy != 0 );
00527       const CtxSet&       ctxSetLast  = ( useYCtx ? Ctx::LastY : Ctx::LastX )[ chType ];
00528       const unsigned      lastShift   = ( compID == COMPONENT_Y ? (log2Size+1)>>2 : Clip3<unsigned>(0,2,size>>3) );
00529       const unsigned      lastOffset  = ( compID == COMPONENT_Y ? ( prefixCtx[log2Size] ) : 0 );
00530       uint32_t            sumFBits    = 0;
00531       unsigned            maxCtxId    = g_uiGroupIdx[std::min<unsigned>(JVET_C0024_ZERO_OUT_TH, size) - 1];
00532       for( unsigned ctxId = 0; ctxId < maxCtxId; ctxId++ )
00533       {
00534         const BinFracBits bits  = fracBitsAccess.getFracBitsArray( ctxSetLast( lastOffset + ( ctxId >> lastShift ) ) );
00535         ctxBits[ ctxId ]        = sumFBits + bits.intBits[0] + ( ctxId>3 ? ((ctxId-2)>>1)<<SCALE_BITS : 0 ) + bitOffset;
00536         sumFBits               +=            bits.intBits[1];
00537       }
00538       ctxBits  [ maxCtxId ]     = sumFBits + ( maxCtxId>3 ? ((maxCtxId-2)>>1)<<SCALE_BITS : 0 ) + bitOffset;
00539       for (unsigned pos = 0; pos < std::min<unsigned>(JVET_C0024_ZERO_OUT_TH, size); pos++)
00540       {
00541         lastBits[ pos ]         = ctxBits[ g_uiGroupIdx[ pos ] ];
00542       }
00543     }
00544   }
00545 
00546   void RateEstimator::xSetSigSbbFracBits( const FracBitsAccess& fracBitsAccess, ChannelType chType )
00547   {
00548     const CtxSet& ctxSet = Ctx::SigCoeffGroup[ chType ];
00549     for( unsigned ctxId = 0; ctxId < sm_maxNumSigSbbCtx; ctxId++ )
00550     {
00551       m_sigSbbFracBits[ ctxId ] = fracBitsAccess.getFracBitsArray( ctxSet( ctxId ) );
00552     }
00553   }
00554 
00555   void RateEstimator::xSetSigFlagBits( const FracBitsAccess& fracBitsAccess, ChannelType chType )
00556   {
00557     for( unsigned ctxSetId = 0; ctxSetId < sm_numCtxSetsSig; ctxSetId++ )
00558     {
00559       BinFracBits*    bits    = m_sigFracBits [ ctxSetId ];
00560       const CtxSet&   ctxSet  = Ctx::SigFlag  [ chType + 2*ctxSetId ];
00561       const unsigned  numCtx  = ( chType == CHANNEL_TYPE_LUMA ? 12 : 8 );
00562       for( unsigned ctxId = 0; ctxId < numCtx; ctxId++ )
00563       {
00564         bits[ ctxId ] = fracBitsAccess.getFracBitsArray( ctxSet( ctxId ) );
00565       }
00566     }
00567   }
00568 
00569   void RateEstimator::xSetGtxFlagBits( const FracBitsAccess& fracBitsAccess, ChannelType chType )
00570   {
00571     const CtxSet&   ctxSetPar   = Ctx::ParFlag [     chType ];
00572     const CtxSet&   ctxSetGt1   = Ctx::GtxFlag [ 2 + chType ];
00573     const CtxSet&   ctxSetGt2   = Ctx::GtxFlag [     chType ];
00574     const unsigned  numCtx      = ( chType == CHANNEL_TYPE_LUMA ? 21 : 11 );
00575     for( unsigned ctxId = 0; ctxId < numCtx; ctxId++ )
00576     {
00577       BinFracBits     fbPar = fracBitsAccess.getFracBitsArray( ctxSetPar( ctxId ) );
00578       BinFracBits     fbGt1 = fracBitsAccess.getFracBitsArray( ctxSetGt1( ctxId ) );
00579       BinFracBits     fbGt2 = fracBitsAccess.getFracBitsArray( ctxSetGt2( ctxId ) );
00580       CoeffFracBits&  cb    = m_gtxFracBits[ ctxId ];
00581       int32_t         par0  = (1<<SCALE_BITS) + int32_t(fbPar.intBits[0]);
00582       int32_t         par1  = (1<<SCALE_BITS) + int32_t(fbPar.intBits[1]);
00583       cb.bits[0] = 0;
00584       cb.bits[1] = fbGt1.intBits[0] + (1 << SCALE_BITS);
00585       cb.bits[2] = fbGt1.intBits[1] + par0 + fbGt2.intBits[0];
00586       cb.bits[3] = fbGt1.intBits[1] + par1 + fbGt2.intBits[0];
00587       cb.bits[4] = fbGt1.intBits[1] + par0 + fbGt2.intBits[1];
00588       cb.bits[5] = fbGt1.intBits[1] + par1 + fbGt2.intBits[1];
00589     }
00590   }
