00625 
00626   class Quantizer
00627   {
00628   public:
00629     Quantizer() {}
00630     void  dequantBlock         ( const TransformUnit& tu, const ComponentID compID, const QpParam& cQP, CoeffBuf& recCoeff, bool enableScalingLists, int* piDequantCoef ) const;
00631     void  initQuantBlock       ( const TransformUnit& tu, const ComponentID compID, const QpParam& cQP, const double lambda, int gValue );
00632     inline void   preQuantCoeff( const TCoeff absCoeff, PQData *pqData, TCoeff quanCoeff ) const;
00633     inline TCoeff getLastThreshold() const { return m_thresLast; }
00634     inline TCoeff getSSbbThreshold() const { return m_thresSSbb; }
00635 
00636     inline int64_t getQScale()       const { return m_QScale; }
00637   private:
00638     // quantization
00639     int               m_QShift;
00640     int64_t           m_QAdd;
00641     int64_t           m_QScale;
00642     TCoeff            m_maxQIdx;
00643     TCoeff            m_thresLast;
00644     TCoeff            m_thresSSbb;
00645     // distortion normalization
00646     int               m_DistShift;
00647     int64_t           m_DistAdd;
00648     int64_t           m_DistStepAdd;
00649     int64_t           m_DistOrgFact;
00650   };
00651 
00652   inline int ceil_log2(uint64_t x)
00653   {
00654     static const uint64_t t[6] = { 0xFFFFFFFF00000000ull, 0x00000000FFFF0000ull, 0x000000000000FF00ull, 0x00000000000000F0ull, 0x000000000000000Cull, 0x0000000000000002ull };
00655     int y = (((x & (x - 1)) == 0) ? 0 : 1);
00656     int j = 32;
00657     for( int i = 0; i < 6; i++)
00658     {
00659       int k = (((x & t[i]) == 0) ? 0 : j);
00660       y += k;
00661       x >>= k;
00662       j >>= 1;
00663     }
00664     return y;
00665   }
00666   void Quantizer::initQuantBlock(const TransformUnit& tu, const ComponentID compID, const QpParam& cQP, const double lambda, int gValue = -1)
00667   {
00668     CHECKD( lambda <= 0.0, "Lambda must be greater than 0" );
00669 
00670     const int         qpDQ                  = cQP.Qp(tu.mtsIdx[compID] == MTS_SKIP) + 1;
00671     const int         qpPer                 = qpDQ / 6;
00672     const int         qpRem                 = qpDQ - 6 * qpPer;
00673     const SPS&        sps                   = *tu.cs->sps;
00674     const CompArea&   area                  = tu.blocks[ compID ];
00675     const ChannelType chType                = toChannelType( compID );
00676     const int         channelBitDepth       = sps.getBitDepth( chType );
00677     const int         maxLog2TrDynamicRange = sps.getMaxLog2TrDynamicRange( chType );
00678     const int         nomTransformShift     = getTransformShift( channelBitDepth, area.size(), maxLog2TrDynamicRange );
00679     const bool        clipTransformShift    = ( tu.mtsIdx[compID] == MTS_SKIP && sps.getSpsRangeExtension().getExtendedPrecisionProcessingFlag());
00680     const bool    needsSqrt2ScaleAdjustment = TU::needsSqrt2Scale(tu, compID);
00681     const int         transformShift        = ( clipTransformShift ? std::max<int>( 0, nomTransformShift ) : nomTransformShift ) + (needsSqrt2ScaleAdjustment?-1:0);
00682     // quant parameters
00683     m_QShift                    = QUANT_SHIFT  - 1 + qpPer + transformShift;
00684     m_QAdd                      = -( ( 3 << m_QShift ) >> 1 );
00685     int               invShift  = IQUANT_SHIFT + 1 - qpPer - transformShift;
00686     m_QScale                    = g_quantScales[needsSqrt2ScaleAdjustment?1:0][ qpRem ];
00687     const unsigned    qIdxBD    = std::min<unsigned>( maxLog2TrDynamicRange + 1, 8*sizeof(Intermediate_Int) + invShift - IQUANT_SHIFT - 1 );
00688     m_maxQIdx                   = ( 1 << (qIdxBD-1) ) - 4;
00689     m_thresLast                 = TCoeff((int64_t(4) << m_QShift));
00690     m_thresSSbb                 = TCoeff((int64_t(3) << m_QShift));
00691     // distortion calculation parameters
00692     const int64_t qScale        = (gValue==-1) ? m_QScale : gValue;
00693     const int nomDShift =
00694       SCALE_BITS - 2 * (nomTransformShift + DISTORTION_PRECISION_ADJUSTMENT(channelBitDepth)) + m_QShift + (needsSqrt2ScaleAdjustment ? 1 : 0);
00695     const double  qScale2       = double( qScale * qScale );
00696     const double  nomDistFactor = ( nomDShift < 0 ? 1.0/(double(int64_t(1)<<(-nomDShift))*qScale2*lambda) : double(int64_t(1)<<nomDShift)/(qScale2*lambda) );
00697     const int64_t pow2dfShift   = (int64_t)( nomDistFactor * qScale2 ) + 1;
00698     const int     dfShift       = ceil_log2( pow2dfShift );
00699     m_DistShift                 = 62 + m_QShift - 2*maxLog2TrDynamicRange - dfShift;
00700     m_DistAdd                   = (int64_t(1) << m_DistShift) >> 1;
00701     m_DistStepAdd               = (int64_t)( nomDistFactor * double(int64_t(1)<<(m_DistShift+m_QShift)) + .5 );
00702     m_DistOrgFact               = (int64_t)( nomDistFactor * double(int64_t(1)<<(m_DistShift+1       )) + .5 );
00703   }
00704 
00705   void Quantizer::dequantBlock( const TransformUnit& tu, const ComponentID compID, const QpParam& cQP, CoeffBuf& recCoeff, bool enableScalingLists, int* piDequantCoef) const
00706   {
00707 
00708     //----- set basic parameters -----
00709     const CompArea&     area      = tu.blocks[ compID ];
00710     const int           numCoeff  = area.area();
00711     const SizeType      hsId      = gp_sizeIdxInfo->idxFrom( area.width  );
00712     const SizeType      vsId      = gp_sizeIdxInfo->idxFrom( area.height );
00713     const CoeffScanType scanType  = SCAN_DIAG;
00714     const ScanElement *scan       = g_scanOrder[SCAN_GROUPED_4x4][scanType][hsId][vsId];
00715     const TCoeff*       qCoeff    = tu.getCoeffs( compID ).buf;
00716           TCoeff*       tCoeff    = recCoeff.buf;
00717 
00718     //----- reset coefficients and get last scan index -----
00719     ::memset( tCoeff, 0, numCoeff * sizeof(TCoeff) );
00720     int lastScanIdx = -1;
00721     for( int scanIdx = numCoeff - 1; scanIdx >= 0; scanIdx-- )
00722     {
00723       if (qCoeff[scan[scanIdx].idx])
00724       {
00725         lastScanIdx = scanIdx;
00726         break;
00727       }
00728     }
00729     if( lastScanIdx < 0 )
00730     {
00731       return;
00732     }
00733 
00734     //----- set dequant parameters -----
00735     const int         qpDQ                  = cQP.Qp(tu.mtsIdx[compID] == MTS_SKIP) + 1;
00736     const int         qpPer                 = qpDQ / 6;
00737     const int         qpRem                 = qpDQ - 6 * qpPer;
00738     const SPS&        sps                   = *tu.cs->sps;
00739     const ChannelType chType                = toChannelType( compID );
00740     const int         channelBitDepth       = sps.getBitDepth( chType );
00741     const int         maxLog2TrDynamicRange = sps.getMaxLog2TrDynamicRange( chType );
00742     const TCoeff      minTCoeff             = -( 1 << maxLog2TrDynamicRange );
00743     const TCoeff      maxTCoeff             =  ( 1 << maxLog2TrDynamicRange ) - 1;
00744     const int         nomTransformShift     = getTransformShift( channelBitDepth, area.size(), maxLog2TrDynamicRange );
00745     const bool        clipTransformShift    = ( tu.mtsIdx[compID] == MTS_SKIP && sps.getSpsRangeExtension().getExtendedPrecisionProcessingFlag());
00746     const bool    needsSqrt2ScaleAdjustment = TU::needsSqrt2Scale(tu, compID);
00747     const int         transformShift        = ( clipTransformShift ? std::max<int>( 0, nomTransformShift ) : nomTransformShift ) + (needsSqrt2ScaleAdjustment?-1:0);
00748     Intermediate_Int  shift                 = IQUANT_SHIFT + 1 - qpPer - transformShift + (enableScalingLists ? LOG2_SCALING_LIST_NEUTRAL_VALUE : 0);
00749     Intermediate_Int  invQScale             = g_invQuantScales[needsSqrt2ScaleAdjustment?1:0][ qpRem ];
00750     Intermediate_Int  add = (shift < 0) ? 0 : ((1 << shift) >> 1);
00751     //----- dequant coefficients -----
00752     for( int state = 0, scanIdx = lastScanIdx; scanIdx >= 0; scanIdx-- )
00753     {
00754       const unsigned  rasterPos = scan[scanIdx].idx;
00755       const TCoeff&   level     = qCoeff[ rasterPos ];
00756       if( level )
00757       {
00758         if (enableScalingLists)
00759           invQScale = piDequantCoef[rasterPos];//scalingfactor*levelScale
00760         if (shift < 0 && (enableScalingLists || scanIdx == lastScanIdx))
00761         {
00762           invQScale <<= -shift;
00763         }
00764         Intermediate_Int  qIdx      = ( level << 1 ) + ( level > 0 ? -(state>>1) : (state>>1) );
00765         int64_t  nomTCoeff          = ((int64_t)qIdx * (int64_t)invQScale + add) >> ((shift < 0) ? 0 : shift);
00766         tCoeff[rasterPos]           = (TCoeff)Clip3<int64_t>(minTCoeff, maxTCoeff, nomTCoeff);
00767       }
00768       state = ( 32040 >> ((state<<2)+((level&1)<<1)) ) & 3;   // the 16-bit value "32040" represent the state transition table
00769     }
00770   }
00771 
00772   inline void Quantizer::preQuantCoeff(const TCoeff absCoeff, PQData *pqData, TCoeff quanCoeff) const
00773   {
00774     int64_t scaledOrg = int64_t( absCoeff ) * quanCoeff;
00775     TCoeff  qIdx      = std::max<TCoeff>( 1, std::min<TCoeff>( m_maxQIdx, TCoeff( ( scaledOrg + m_QAdd ) >> m_QShift ) ) );
00776     int64_t scaledAdd = qIdx * m_DistStepAdd - scaledOrg * m_DistOrgFact;
00777     PQData& pq_a      = pqData[ qIdx & 3 ];
00778     pq_a.deltaDist    = ( scaledAdd * qIdx + m_DistAdd ) >> m_DistShift;
00779     pq_a.absLevel     = ( ++qIdx ) >> 1;
00780     scaledAdd        += m_DistStepAdd;
00781     PQData& pq_b      = pqData[ qIdx & 3 ];
00782     pq_b.deltaDist    = ( scaledAdd * qIdx + m_DistAdd ) >> m_DistShift;
00783     pq_b.absLevel     = ( ++qIdx ) >> 1;
00784     scaledAdd        += m_DistStepAdd;
00785     PQData& pq_c      = pqData[ qIdx & 3 ];
00786     pq_c.deltaDist    = ( scaledAdd * qIdx + m_DistAdd ) >> m_DistShift;
00787     pq_c.absLevel     = ( ++qIdx ) >> 1;
00788     scaledAdd        += m_DistStepAdd;
00789     PQData& pq_d      = pqData[ qIdx & 3 ];
00790     pq_d.deltaDist    = ( scaledAdd * qIdx + m_DistAdd ) >> m_DistShift;
00791     pq_d.absLevel     = ( ++qIdx ) >> 1;
00792   }
