00845 
00846 #define RICEMAX 32
00847   const int32_t g_goRiceBits[4][RICEMAX] =
00848   {
00849     { 32768,  65536,  98304, 131072, 163840, 196608, 262144, 262144, 327680, 327680, 327680, 327680, 393216, 393216, 393216, 393216, 393216, 393216, 393216, 393216, 458752, 458752, 458752, 458752, 458752, 458752, 458752, 458752, 458752, 458752, 458752, 458752},
00850     { 65536,  65536,  98304,  98304, 131072, 131072, 163840, 163840, 196608, 196608, 229376, 229376, 294912, 294912, 294912, 294912, 360448, 360448, 360448, 360448, 360448, 360448, 360448, 360448, 425984, 425984, 425984, 425984, 425984, 425984, 425984, 425984},
00851     { 98304,  98304,  98304,  98304, 131072, 131072, 131072, 131072, 163840, 163840, 163840, 163840, 196608, 196608, 196608, 196608, 229376, 229376, 229376, 229376, 262144, 262144, 262144, 262144, 327680, 327680, 327680, 327680, 327680, 327680, 327680, 327680},
00852     {131072, 131072, 131072, 131072, 131072, 131072, 131072, 131072, 163840, 163840, 163840, 163840, 163840, 163840, 163840, 163840, 196608, 196608, 196608, 196608, 196608, 196608, 196608, 196608, 229376, 229376, 229376, 229376, 229376, 229376, 229376, 229376}
00853   };
00854 
00855   class State
00856   {
00857     friend class CommonCtx;
00858   public:
00859     State( const RateEstimator& rateEst, CommonCtx& commonCtx, const int stateId );
00860 
00861     template<uint8_t numIPos>
00862     inline void updateState(const ScanInfo &scanInfo, const State *prevStates, const Decision &decision);
00863     inline void updateStateEOS(const ScanInfo &scanInfo, const State *prevStates, const State *skipStates,
00864                                const Decision &decision);
00865 
00866     inline void init()
00867     {
00868       m_rdCost        = std::numeric_limits<int64_t>::max()>>1;
00869       m_numSigSbb     = 0;
00870       m_remRegBins    = 4;  // just large enough for last scan pos
00871       m_refSbbCtxId   = -1;
00872       m_sigFracBits   = m_sigFracBitsArray[ 0 ];
00873       m_coeffFracBits = m_gtxFracBitsArray[ 0 ];
00874       m_goRicePar     = 0;
00875       m_goRiceZero    = 0;
00876     }
00877     void checkRdCosts( const ScanPosType spt, const PQData& pqDataA, const PQData& pqDataB, Decision& decisionA, Decision& decisionB ) const
00878     {
00879       const int32_t*  goRiceTab = g_goRiceBits[m_goRicePar];
00880       int64_t         rdCostA   = m_rdCost + pqDataA.deltaDist;
00881       int64_t         rdCostB   = m_rdCost + pqDataB.deltaDist;
00882       int64_t         rdCostZ   = m_rdCost;
00883         if( m_remRegBins >= 4 )
00884         {
00885           if( pqDataA.absLevel < 4 )
00886             rdCostA += m_coeffFracBits.bits[ pqDataA.absLevel ];
00887           else
00888           {
00889             const TCoeff value = ( pqDataA.absLevel - 4 ) >> 1;
00890             rdCostA += m_coeffFracBits.bits[ pqDataA.absLevel - ( value << 1 ) ] + goRiceTab[ value < RICEMAX ? value : RICEMAX - 1 ];
00891           }
00892           if( pqDataB.absLevel < 4 )
00893             rdCostB += m_coeffFracBits.bits[ pqDataB.absLevel ];
00894           else
00895           {
00896             const TCoeff value = ( pqDataB.absLevel - 4 ) >> 1;
00897             rdCostB += m_coeffFracBits.bits[ pqDataB.absLevel - ( value << 1 ) ] + goRiceTab[ value < RICEMAX ? value : RICEMAX - 1 ];
00898           }
00899           if( spt == SCAN_ISCSBB )
00900           {
00901             rdCostA += m_sigFracBits.intBits[ 1 ];
00902             rdCostB += m_sigFracBits.intBits[ 1 ];
00903             rdCostZ += m_sigFracBits.intBits[ 0 ];
00904           }
00905           else if( spt == SCAN_SOCSBB )
00906           {
00907             rdCostA += m_sbbFracBits.intBits[ 1 ] + m_sigFracBits.intBits[ 1 ];
00908             rdCostB += m_sbbFracBits.intBits[ 1 ] + m_sigFracBits.intBits[ 1 ];
00909             rdCostZ += m_sbbFracBits.intBits[ 1 ] + m_sigFracBits.intBits[ 0 ];
00910           }
00911           else if( m_numSigSbb )
00912           {
00913             rdCostA += m_sigFracBits.intBits[ 1 ];
00914             rdCostB += m_sigFracBits.intBits[ 1 ];
00915             rdCostZ += m_sigFracBits.intBits[ 0 ];
00916           }
00917           else
00918           {
00919             rdCostZ = decisionA.rdCost;
00920           }
00921         }
00922         else
00923         {
00924           rdCostA += ( 1 << SCALE_BITS ) + goRiceTab[ pqDataA.absLevel <= m_goRiceZero ? pqDataA.absLevel - 1 : ( pqDataA.absLevel < RICEMAX ? pqDataA.absLevel : RICEMAX - 1 ) ];
00925           rdCostB += ( 1 << SCALE_BITS ) + goRiceTab[ pqDataB.absLevel <= m_goRiceZero ? pqDataB.absLevel - 1 : ( pqDataB.absLevel < RICEMAX ? pqDataB.absLevel : RICEMAX - 1 ) ];
00926           rdCostZ += goRiceTab[ m_goRiceZero ];
00927         }
00928         if( rdCostA < decisionA.rdCost )
00929         {
00930           decisionA.rdCost = rdCostA;
00931           decisionA.absLevel = pqDataA.absLevel;
00932           decisionA.prevId = m_stateId;
00933         }
00934         if( rdCostZ < decisionA.rdCost )
00935         {
00936           decisionA.rdCost = rdCostZ;
00937           decisionA.absLevel = 0;
00938           decisionA.prevId = m_stateId;
00939         }
00940         if( rdCostB < decisionB.rdCost )
00941         {
00942           decisionB.rdCost = rdCostB;
00943           decisionB.absLevel = pqDataB.absLevel;
00944           decisionB.prevId = m_stateId;
00945         }
00946       }
00947 
00948     inline void checkRdCostStart(int32_t lastOffset, const PQData &pqData, Decision &decision) const
00949     {
00950       int64_t rdCost = pqData.deltaDist + lastOffset;
00951       if (pqData.absLevel < 4)
00952       {
00953         rdCost += m_coeffFracBits.bits[pqData.absLevel];
00954       }
00955       else
00956       {
00957         const TCoeff value = (pqData.absLevel - 4) >> 1;
00958         rdCost += m_coeffFracBits.bits[pqData.absLevel - (value << 1)] + g_goRiceBits[m_goRicePar][value < RICEMAX ? value : RICEMAX-1];
00959       }
00960       if( rdCost < decision.rdCost )
00961       {
00962         decision.rdCost   = rdCost;
00963         decision.absLevel = pqData.absLevel;
00964         decision.prevId   = -1;
00965       }
00966     }
00967 
00968     inline void checkRdCostSkipSbb(Decision &decision) const
00969     {
00970       int64_t rdCost = m_rdCost + m_sbbFracBits.intBits[0];
00971       if( rdCost < decision.rdCost )
00972       {
00973         decision.rdCost   = rdCost;
00974         decision.absLevel = 0;
00975         decision.prevId   = 4+m_stateId;
00976       }
00977     }
00978 
00979     inline void checkRdCostSkipSbbZeroOut(Decision &decision) const
00980     {
00981       int64_t rdCost = m_rdCost + m_sbbFracBits.intBits[0];
00982       decision.rdCost = rdCost;
00983       decision.absLevel = 0;
00984       decision.prevId = 4 + m_stateId;
00985     }
00986 
00987   private:
00988     int64_t                   m_rdCost;
00989     uint16_t                  m_absLevelsAndCtxInit[24];  // 16x8bit for abs levels + 16x16bit for ctx init id
00990     int8_t                    m_numSigSbb;
00991     int                       m_remRegBins;
00992     int8_t                    m_refSbbCtxId;
00993     BinFracBits               m_sbbFracBits;
00994     BinFracBits               m_sigFracBits;
00995     CoeffFracBits             m_coeffFracBits;
00996     int8_t                    m_goRicePar;
00997     int8_t                    m_goRiceZero;
00998     const int8_t              m_stateId;
00999     const BinFracBits*const   m_sigFracBitsArray;
01000     const CoeffFracBits*const m_gtxFracBitsArray;
01001     CommonCtx&                m_commonCtx;
01002   public:
01003     unsigned                  effWidth;
01004     unsigned                  effHeight;
01005   };
