01010     , m_stateId         ( stateId )
01011     , m_sigFracBitsArray( rateEst.sigFlagBits(stateId) )
01012     , m_gtxFracBitsArray( rateEst.gtxFracBits(stateId) )
01013     , m_commonCtx       ( commonCtx )
