01017   template<uint8_t numIPos>
01018   inline void State::updateState(const ScanInfo &scanInfo, const State *prevStates, const Decision &decision)
01019   {
01020     m_rdCost = decision.rdCost;
01021     if( decision.prevId > -2 )
01022     {
01023       if( decision.prevId >= 0 )
01024       {
01025         const State*  prvState  = prevStates            +   decision.prevId;
01026         m_numSigSbb             = prvState->m_numSigSbb + !!decision.absLevel;
01027         m_refSbbCtxId           = prvState->m_refSbbCtxId;
01028         m_sbbFracBits           = prvState->m_sbbFracBits;
01029         m_remRegBins            = prvState->m_remRegBins - 1;
01030         m_goRicePar             = prvState->m_goRicePar;
01031         if( m_remRegBins >= 4 )
01032         {
01033           m_remRegBins -= (decision.absLevel < 2 ? (unsigned)decision.absLevel : 3);
01034         }
01035         ::memcpy( m_absLevelsAndCtxInit, prvState->m_absLevelsAndCtxInit, 48*sizeof(uint8_t) );
01036       }
01037       else
01038       {
01039         m_numSigSbb     =  1;
01040         m_refSbbCtxId   = -1;
01041         int ctxBinSampleRatio = (scanInfo.chType == CHANNEL_TYPE_LUMA) ? MAX_TU_LEVEL_CTX_CODED_BIN_CONSTRAINT_LUMA : MAX_TU_LEVEL_CTX_CODED_BIN_CONSTRAINT_CHROMA;
01042         m_remRegBins = (effWidth * effHeight *ctxBinSampleRatio) / 16 - (decision.absLevel < 2 ? (unsigned)decision.absLevel : 3);
01043         ::memset( m_absLevelsAndCtxInit, 0, 48*sizeof(uint8_t) );
01044       }
01045 
01046       uint8_t* levels               = reinterpret_cast<uint8_t*>(m_absLevelsAndCtxInit);
01047       levels[ scanInfo.insidePos ]  = (uint8_t)std::min<TCoeff>( 255, decision.absLevel );
01048 
01049       if (m_remRegBins >= 4)
01050       {
01051         TCoeff  tinit = m_absLevelsAndCtxInit[8 + scanInfo.nextInsidePos];
01052         TCoeff  sumAbs1 = (tinit >> 3) & 31;
01053         TCoeff  sumNum = tinit & 7;
01054 #define UPDATE(k) {TCoeff t=levels[scanInfo.nextNbInfoSbb.inPos[k]]; sumAbs1+=std::min<TCoeff>(4+(t&1),t); sumNum+=!!t; }
01055         if (numIPos == 1)
01056         {
01057           UPDATE(0);
01058         }
01059         else if (numIPos == 2)
01060         {
01061           UPDATE(0);
01062           UPDATE(1);
01063         }
01064         else if (numIPos == 3)
01065         {
01066           UPDATE(0);
01067           UPDATE(1);
01068           UPDATE(2);
01069         }
01070         else if (numIPos == 4)
01071         {
01072           UPDATE(0);
01073           UPDATE(1);
01074           UPDATE(2);
01075           UPDATE(3);
01076         }
01077         else if (numIPos == 5)
01078         {
01079           UPDATE(0);
01080           UPDATE(1);
01081           UPDATE(2);
01082           UPDATE(3);
01083           UPDATE(4);
01084         }
01085 #undef UPDATE
01086         TCoeff sumGt1 = sumAbs1 - sumNum;
01087         m_sigFracBits = m_sigFracBitsArray[scanInfo.sigCtxOffsetNext + std::min<TCoeff>( (sumAbs1+1)>>1, 3 )];
01088         m_coeffFracBits = m_gtxFracBitsArray[scanInfo.gtxCtxOffsetNext + (sumGt1 < 4 ? sumGt1 : 4)];
01089 
01090         TCoeff  sumAbs = m_absLevelsAndCtxInit[8 + scanInfo.nextInsidePos] >> 8;
01091 #define UPDATE(k) {TCoeff t=levels[scanInfo.nextNbInfoSbb.inPos[k]]; sumAbs+=t; }
01092         if (numIPos == 1)
01093         {
01094           UPDATE(0);
01095         }
01096         else if (numIPos == 2)
01097         {
01098           UPDATE(0);
01099           UPDATE(1);
01100         }
01101         else if (numIPos == 3)
01102         {
01103           UPDATE(0);
01104           UPDATE(1);
01105           UPDATE(2);
01106         }
01107         else if (numIPos == 4)
01108         {
01109           UPDATE(0);
01110           UPDATE(1);
01111           UPDATE(2);
01112           UPDATE(3);
01113         }
01114         else if (numIPos == 5)
01115         {
01116           UPDATE(0);
01117           UPDATE(1);
01118           UPDATE(2);
01119           UPDATE(3);
01120           UPDATE(4);
01121         }
01122 #undef UPDATE
01123         int sumAll = std::max(std::min(31, (int)sumAbs - 4 * 5), 0);
01124         m_goRicePar = g_auiGoRiceParsCoeff[sumAll];
01125       }
01126       else
01127       {
01128         TCoeff  sumAbs = m_absLevelsAndCtxInit[8 + scanInfo.nextInsidePos] >> 8;
01129 #define UPDATE(k) {TCoeff t=levels[scanInfo.nextNbInfoSbb.inPos[k]]; sumAbs+=t; }
01130         if (numIPos == 1)
01131         {
01132           UPDATE(0);
01133         }
01134         else if (numIPos == 2)
01135         {
01136           UPDATE(0);
01137           UPDATE(1);
01138         }
01139         else if (numIPos == 3)
01140         {
01141           UPDATE(0);
01142           UPDATE(1);
01143           UPDATE(2);
01144         }
01145         else if (numIPos == 4)
01146         {
01147           UPDATE(0);
01148           UPDATE(1);
01149           UPDATE(2);
01150           UPDATE(3);
01151         }
01152         else if (numIPos == 5)
01153         {
01154           UPDATE(0);
01155           UPDATE(1);
01156           UPDATE(2);
01157           UPDATE(3);
01158           UPDATE(4);
01159         }
01160 #undef UPDATE
01161         sumAbs = std::min<TCoeff>(31, sumAbs);
01162         m_goRicePar = g_auiGoRiceParsCoeff[sumAbs];
01163         m_goRiceZero = g_auiGoRicePosCoeff0(m_stateId, m_goRicePar);
01164       }
01165     }
01166   }
01167 
01168   inline void State::updateStateEOS(const ScanInfo &scanInfo, const State *prevStates, const State *skipStates,
01169                                     const Decision &decision)
01170   {
01171     m_rdCost = decision.rdCost;
01172     if( decision.prevId > -2 )
01173     {
01174       const State* prvState = 0;
01175       if( decision.prevId  >= 4 )
01176       {
01177         CHECK( decision.absLevel != 0, "cannot happen" );
01178         prvState    = skipStates + ( decision.prevId - 4 );
01179         m_numSigSbb = 0;
01180         ::memset( m_absLevelsAndCtxInit, 0, 16*sizeof(uint8_t) );
01181       }
01182       else if( decision.prevId  >= 0 )
01183       {
01184         prvState    = prevStates            +   decision.prevId;
01185         m_numSigSbb = prvState->m_numSigSbb + !!decision.absLevel;
01186         ::memcpy( m_absLevelsAndCtxInit, prvState->m_absLevelsAndCtxInit, 16*sizeof(uint8_t) );
01187       }
01188       else
01189       {
01190         m_numSigSbb = 1;
01191         ::memset( m_absLevelsAndCtxInit, 0, 16*sizeof(uint8_t) );
01192       }
01193       reinterpret_cast<uint8_t*>(m_absLevelsAndCtxInit)[ scanInfo.insidePos ] = (uint8_t)std::min<TCoeff>( 255, decision.absLevel );
01194 
01195       m_commonCtx.update( scanInfo, prvState, *this );
01196 
01197       TCoeff  tinit   = m_absLevelsAndCtxInit[ 8 + scanInfo.nextInsidePos ];
01198       TCoeff  sumNum  =   tinit        & 7;
01199       TCoeff  sumAbs1 = ( tinit >> 3 ) & 31;
01200       TCoeff  sumGt1  = sumAbs1        - sumNum;
01201       m_sigFracBits   = m_sigFracBitsArray[ scanInfo.sigCtxOffsetNext + std::min<TCoeff>( (sumAbs1+1)>>1, 3 ) ];
01202       m_coeffFracBits = m_gtxFracBitsArray[ scanInfo.gtxCtxOffsetNext + ( sumGt1  < 4 ? sumGt1  : 4 ) ];
01203     }
01204   }
01205 
01206   inline void CommonCtx::update(const ScanInfo &scanInfo, const State *prevState, State &currState)
01207   {
01208     uint8_t*    sbbFlags  = m_currSbbCtx[ currState.m_stateId ].sbbFlags;
01209     uint8_t*    levels    = m_currSbbCtx[ currState.m_stateId ].levels;
01210     std::size_t setCpSize = m_nbInfo[ scanInfo.scanIdx - 1 ].maxDist * sizeof(uint8_t);
01211     if( prevState && prevState->m_refSbbCtxId >= 0 )
01212     {
01213       ::memcpy( sbbFlags,                  m_prevSbbCtx[prevState->m_refSbbCtxId].sbbFlags,                  scanInfo.numSbb*sizeof(uint8_t) );
01214       ::memcpy( levels + scanInfo.scanIdx, m_prevSbbCtx[prevState->m_refSbbCtxId].levels + scanInfo.scanIdx, setCpSize );
01215     }
01216     else
01217     {
01218       ::memset( sbbFlags,                  0, scanInfo.numSbb*sizeof(uint8_t) );
01219       ::memset( levels + scanInfo.scanIdx, 0, setCpSize );
01220     }
01221     sbbFlags[ scanInfo.sbbPos ] = !!currState.m_numSigSbb;
01222     ::memcpy( levels + scanInfo.scanIdx, currState.m_absLevelsAndCtxInit, scanInfo.sbbSize*sizeof(uint8_t) );
01223 
01224     const int       sigNSbb   = ( ( scanInfo.nextSbbRight ? sbbFlags[ scanInfo.nextSbbRight ] : false ) || ( scanInfo.nextSbbBelow ? sbbFlags[ scanInfo.nextSbbBelow ] : false ) ? 1 : 0 );
01225     currState.m_numSigSbb     = 0;
01226     if (prevState)
01227     {
01228       currState.m_remRegBins = prevState->m_remRegBins;
01229     }
01230     else
01231     {
01232       int ctxBinSampleRatio = (scanInfo.chType == CHANNEL_TYPE_LUMA) ? MAX_TU_LEVEL_CTX_CODED_BIN_CONSTRAINT_LUMA : MAX_TU_LEVEL_CTX_CODED_BIN_CONSTRAINT_CHROMA;
01233       currState.m_remRegBins = (currState.effWidth * currState.effHeight *ctxBinSampleRatio) / 16;
01234     }
01235     currState.m_goRicePar     = 0;
01236     currState.m_refSbbCtxId   = currState.m_stateId;
01237     currState.m_sbbFracBits   = m_sbbFlagBits[ sigNSbb ];
01238 
01239     uint16_t          templateCtxInit[16];
01240     const int         scanBeg   = scanInfo.scanIdx - scanInfo.sbbSize;
01241     const NbInfoOut*  nbOut     = m_nbInfo + scanBeg;
01242     const uint8_t*    absLevels = levels   + scanBeg;
01243     for( int id = 0; id < scanInfo.sbbSize; id++, nbOut++ )
01244     {
01245       if( nbOut->num )
01246       {
01247         TCoeff sumAbs = 0, sumAbs1 = 0, sumNum = 0;
01248 #define UPDATE(k) {TCoeff t=absLevels[nbOut->outPos[k]]; sumAbs+=t; sumAbs1+=std::min<TCoeff>(4+(t&1),t); sumNum+=!!t; }
01249         UPDATE(0);
01250         if( nbOut->num > 1 )
01251         {
01252           UPDATE(1);
01253           if( nbOut->num > 2 )
01254           {
01255             UPDATE(2);
01256             if( nbOut->num > 3 )
01257             {
01258               UPDATE(3);
01259               if( nbOut->num > 4 )
01260               {
01261                 UPDATE(4);
01262               }
01263             }
01264           }
01265         }
01266 #undef UPDATE
01267         templateCtxInit[id] = uint16_t(sumNum) + ( uint16_t(sumAbs1) << 3 ) + ( (uint16_t)std::min<TCoeff>( 127, sumAbs ) << 8 );
01268       }
01269       else
01270       {
01271         templateCtxInit[id] = 0;
01272       }
01273     }
01274     ::memset( currState.m_absLevelsAndCtxInit,     0,               16*sizeof(uint8_t) );
01275     ::memcpy( currState.m_absLevelsAndCtxInit + 8, templateCtxInit, 16*sizeof(uint16_t) );
01276   }
