01309 #define TINIT(x) {*this,m_commonCtx,x}
01310   DepQuant::DepQuant()
01311     : RateEstimator ()
01312     , m_commonCtx   ()
01313     , m_allStates   {TINIT(0),TINIT(1),TINIT(2),TINIT(3),TINIT(0),TINIT(1),TINIT(2),TINIT(3),TINIT(0),TINIT(1),TINIT(2),TINIT(3)}
01314     , m_currStates  (  m_allStates      )
01315     , m_prevStates  (  m_currStates + 4 )
01316     , m_skipStates  (  m_prevStates + 4 )
01317     , m_startState  TINIT(0)
