01332 
01333   void DepQuant::xDecide( const ScanPosType spt, const TCoeff absCoeff, const int lastOffset, Decision* decisions, bool zeroOut, TCoeff quanCoeff)
01334   {
01335     ::memcpy( decisions, startDec, 8*sizeof(Decision) );
01336 
01337     if( zeroOut )
01338     {
01339       if( spt==SCAN_EOCSBB )
01340       {
01341         m_skipStates[0].checkRdCostSkipSbbZeroOut( decisions[0] );
01342         m_skipStates[1].checkRdCostSkipSbbZeroOut( decisions[1] );
01343         m_skipStates[2].checkRdCostSkipSbbZeroOut( decisions[2] );
01344         m_skipStates[3].checkRdCostSkipSbbZeroOut( decisions[3] );
01345       }
01346       return;
01347     }
01348 
01349     PQData  pqData[4];
01350     m_quant.preQuantCoeff( absCoeff, pqData, quanCoeff );
01351     m_prevStates[0].checkRdCosts( spt, pqData[0], pqData[2], decisions[0], decisions[2]);
01352     m_prevStates[1].checkRdCosts( spt, pqData[0], pqData[2], decisions[2], decisions[0]);
01353     m_prevStates[2].checkRdCosts( spt, pqData[3], pqData[1], decisions[1], decisions[3]);
01354     m_prevStates[3].checkRdCosts( spt, pqData[3], pqData[1], decisions[3], decisions[1]);
01355     if( spt==SCAN_EOCSBB )
01356     {
01357         m_skipStates[0].checkRdCostSkipSbb( decisions[0] );
01358         m_skipStates[1].checkRdCostSkipSbb( decisions[1] );
01359         m_skipStates[2].checkRdCostSkipSbb( decisions[2] );
01360         m_skipStates[3].checkRdCostSkipSbb( decisions[3] );
01361     }
01362 
01363     m_startState.checkRdCostStart( lastOffset, pqData[0], decisions[0] );
01364     m_startState.checkRdCostStart( lastOffset, pqData[2], decisions[2] );
01365   }
01366 
01367   void DepQuant::xDecideAndUpdate( const TCoeff absCoeff, const ScanInfo& scanInfo, bool zeroOut, TCoeff quantCoeff )
01368   {
01369     Decision* decisions = m_trellis[ scanInfo.scanIdx ];
01370 
01371     std::swap( m_prevStates, m_currStates );
01372 
01373     xDecide( scanInfo.spt, absCoeff, lastOffset(scanInfo.scanIdx), decisions, zeroOut, quantCoeff );
01374 
01375     if( scanInfo.scanIdx )
01376     {
01377       if( scanInfo.eosbb )
01378       {
01379         m_commonCtx.swap();
01380         m_currStates[0].updateStateEOS( scanInfo, m_prevStates, m_skipStates, decisions[0] );
01381         m_currStates[1].updateStateEOS( scanInfo, m_prevStates, m_skipStates, decisions[1] );
01382         m_currStates[2].updateStateEOS( scanInfo, m_prevStates, m_skipStates, decisions[2] );
01383         m_currStates[3].updateStateEOS( scanInfo, m_prevStates, m_skipStates, decisions[3] );
01384         ::memcpy( decisions+4, decisions, 4*sizeof(Decision) );
01385       }
01386       else if( !zeroOut )
01387       {
01388         switch( scanInfo.nextNbInfoSbb.num )
01389         {
01390         case 0:
01391           m_currStates[0].updateState<0>( scanInfo, m_prevStates, decisions[0] );
01392           m_currStates[1].updateState<0>( scanInfo, m_prevStates, decisions[1] );
01393           m_currStates[2].updateState<0>( scanInfo, m_prevStates, decisions[2] );
01394           m_currStates[3].updateState<0>( scanInfo, m_prevStates, decisions[3] );
01395           break;
01396         case 1:
01397           m_currStates[0].updateState<1>( scanInfo, m_prevStates, decisions[0] );
01398           m_currStates[1].updateState<1>( scanInfo, m_prevStates, decisions[1] );
01399           m_currStates[2].updateState<1>( scanInfo, m_prevStates, decisions[2] );
01400           m_currStates[3].updateState<1>( scanInfo, m_prevStates, decisions[3] );
01401           break;
01402         case 2:
01403           m_currStates[0].updateState<2>( scanInfo, m_prevStates, decisions[0] );
01404           m_currStates[1].updateState<2>( scanInfo, m_prevStates, decisions[1] );
01405           m_currStates[2].updateState<2>( scanInfo, m_prevStates, decisions[2] );
01406           m_currStates[3].updateState<2>( scanInfo, m_prevStates, decisions[3] );
01407           break;
01408         case 3:
01409           m_currStates[0].updateState<3>( scanInfo, m_prevStates, decisions[0] );
01410           m_currStates[1].updateState<3>( scanInfo, m_prevStates, decisions[1] );
01411           m_currStates[2].updateState<3>( scanInfo, m_prevStates, decisions[2] );
01412           m_currStates[3].updateState<3>( scanInfo, m_prevStates, decisions[3] );
01413           break;
01414         case 4:
01415           m_currStates[0].updateState<4>( scanInfo, m_prevStates, decisions[0] );
01416           m_currStates[1].updateState<4>( scanInfo, m_prevStates, decisions[1] );
01417           m_currStates[2].updateState<4>( scanInfo, m_prevStates, decisions[2] );
01418           m_currStates[3].updateState<4>( scanInfo, m_prevStates, decisions[3] );
01419           break;
01420         default:
01421           m_currStates[0].updateState<5>( scanInfo, m_prevStates, decisions[0] );
01422           m_currStates[1].updateState<5>( scanInfo, m_prevStates, decisions[1] );
01423           m_currStates[2].updateState<5>( scanInfo, m_prevStates, decisions[2] );
01424           m_currStates[3].updateState<5>( scanInfo, m_prevStates, decisions[3] );
01425         }
01426       }
01427 
01428       if( scanInfo.spt == SCAN_SOCSBB )
01429       {
01430         std::swap( m_prevStates, m_skipStates );
01431       }
01432     }
01433   }
01434 
01435 
01436   void DepQuant::quant( TransformUnit& tu, const CCoeffBuf& srcCoeff, const ComponentID compID, const QpParam& cQP, const double lambda, const Ctx& ctx, TCoeff& absSum, bool enableScalingLists, int* quantCoeff )
01437   {
01438     CHECKD( tu.cs->sps->getSpsRangeExtension().getExtendedPrecisionProcessingFlag(), "ext precision is not supported" );
01439 
01440     //===== reset / pre-init =====
01441     const TUParameters& tuPars  = *g_Rom.getTUPars( tu.blocks[compID], compID );
01442     m_quant.initQuantBlock    ( tu, compID, cQP, lambda );
01443     TCoeff*       qCoeff      = tu.getCoeffs( compID ).buf;
01444     const TCoeff* tCoeff      = srcCoeff.buf;
01445     const int     numCoeff    = tu.blocks[compID].area();
01446     ::memset( tu.getCoeffs( compID ).buf, 0x00, numCoeff*sizeof(TCoeff) );
01447     absSum          = 0;
01448 
01449     const CompArea& area     = tu.blocks[ compID ];
01450     const uint32_t  width    = area.width;
01451     const uint32_t  height   = area.height;
01452     const uint32_t  lfnstIdx = tu.cu->lfnstIdx;
01453     //===== scaling matrix ====
01454     //const int         qpDQ = cQP.Qp + 1;
01455     //const int         qpPer = qpDQ / 6;
01456     //const int         qpRem = qpDQ - 6 * qpPer;
01457 
01458     //TCoeff thresTmp = thres;
01459     bool zeroOut = false;
01460     bool zeroOutforThres = false;
01461     int effWidth = tuPars.m_width, effHeight = tuPars.m_height;
01462     if( ( tu.mtsIdx[compID] > MTS_SKIP || (tu.cs->sps->getUseMTS() && tu.cu->sbtInfo != 0 && tuPars.m_height <= 32 && tuPars.m_width <= 32)) && compID == COMPONENT_Y)
01463     {
01464       effHeight = (tuPars.m_height == 32) ? 16 : tuPars.m_height;
01465       effWidth = (tuPars.m_width == 32) ? 16 : tuPars.m_width;
01466       zeroOut = (effHeight < tuPars.m_height || effWidth < tuPars.m_width);
01467     }
01468     zeroOutforThres = zeroOut || (32 < tuPars.m_height || 32 < tuPars.m_width);
01469     //===== find first test position =====
01470     int firstTestPos = numCoeff - 1;
01471     if (lfnstIdx > 0 && tu.mtsIdx[compID] != MTS_SKIP && width >= 4 && height >= 4)
01472     {
01473       firstTestPos = ( ( width == 4 && height == 4 ) || ( width == 8 && height == 8 ) )  ? 7 : 15 ;
01474     }
01475     const TCoeff defaultQuantisationCoefficient = (TCoeff)m_quant.getQScale();
01476     const TCoeff thres = m_quant.getLastThreshold();
01477     for( ; firstTestPos >= 0; firstTestPos-- )
01478     {
01479       if (zeroOutforThres && (tuPars.m_scanId2BlkPos[firstTestPos].x >= ((tuPars.m_width == 32 && zeroOut) ? 16 : 32)
01480                            || tuPars.m_scanId2BlkPos[firstTestPos].y >= ((tuPars.m_height == 32 && zeroOut) ? 16 : 32)))
01481         continue;
01482       TCoeff thresTmp = (enableScalingLists) ? TCoeff(thres / (4 * quantCoeff[tuPars.m_scanId2BlkPos[firstTestPos].idx]))
01483                                              : TCoeff(thres / (4 * defaultQuantisationCoefficient));
01484 
01485       if (abs(tCoeff[tuPars.m_scanId2BlkPos[firstTestPos].idx]) > thresTmp)
01486       {
01487         break;
01488       }
01489     }
01490     if( firstTestPos < 0 )
01491     {
01492       return;
01493     }
01494 
01495     //===== real init =====
01496     RateEstimator::initCtx( tuPars, tu, compID, ctx.getFracBitsAcess() );
01497     m_commonCtx.reset( tuPars, *this );
01498     for( int k = 0; k < 12; k++ )
01499     {
01500       m_allStates[k].init();
01501     }
01502     m_startState.init();
01503 
01504 
01505     int effectWidth = std::min(32, effWidth);
01506     int effectHeight = std::min(32, effHeight);
01507     for (int k = 0; k < 12; k++)
01508     {
01509       m_allStates[k].effWidth = effectWidth;
01510       m_allStates[k].effHeight = effectHeight;
01511     }
01512     m_startState.effWidth = effectWidth;
01513     m_startState.effHeight = effectHeight;
01514 
01515     //===== populate trellis =====
01516     for( int scanIdx = firstTestPos; scanIdx >= 0; scanIdx-- )
01517     {
01518       const ScanInfo& scanInfo = tuPars.m_scanInfo[ scanIdx ];
01519       if (enableScalingLists)
01520       {
01521         m_quant.initQuantBlock(tu, compID, cQP, lambda, quantCoeff[scanInfo.rasterPos]);
01522         xDecideAndUpdate( abs( tCoeff[scanInfo.rasterPos]), scanInfo, (zeroOut && (scanInfo.posX >= effWidth || scanInfo.posY >= effHeight)), quantCoeff[scanInfo.rasterPos] );
01523       }
01524       else
01525         xDecideAndUpdate( abs( tCoeff[scanInfo.rasterPos]), scanInfo, (zeroOut && (scanInfo.posX >= effWidth || scanInfo.posY >= effHeight)), defaultQuantisationCoefficient );
01526     }
01527 
01528     //===== find best path =====
01529     Decision  decision    = { std::numeric_limits<int64_t>::max(), -1, -2 };
01530     int64_t   minPathCost =  0;
01531     for( int8_t stateId = 0; stateId < 4; stateId++ )
01532     {
01533       int64_t pathCost = m_trellis[0][stateId].rdCost;
01534       if( pathCost < minPathCost )
01535       {
01536         decision.prevId = stateId;
01537         minPathCost     = pathCost;
01538       }
01539     }
01540 
01541     //===== backward scanning =====
01542     int scanIdx = 0;
01543     for( ; decision.prevId >= 0; scanIdx++ )
01544     {
01545       decision          = m_trellis[ scanIdx ][ decision.prevId ];
01546       int32_t blkpos    = tuPars.m_scanId2BlkPos[scanIdx].idx;
01547       qCoeff[ blkpos ]  = ( tCoeff[ blkpos ] < 0 ? -decision.absLevel : decision.absLevel );
01548       absSum           += decision.absLevel;
01549     }
01550   }
01551 
