01558 DepQuant::DepQuant( const Quant* other, bool enc ) : QuantRDOQ( other )
01559 {
01560   const DepQuant* dq = dynamic_cast<const DepQuant*>( other );
01561   CHECK( other && !dq, "The DepQuant cast must be successfull!" );
01562   p = new DQIntern::DepQuant();
01563   if( enc )
01564   {
01565     DQIntern::g_Rom.init();
