01573 
01574 void DepQuant::quant( TransformUnit &tu, const ComponentID &compID, const CCoeffBuf &pSrc, TCoeff &uiAbsSum, const QpParam &cQP, const Ctx& ctx )
01575 {
01576   const bool useRegularResidualCoding = tu.cu->slice->getTSResidualCodingDisabledFlag() || tu.mtsIdx[compID] != MTS_SKIP;
01577   if( tu.cs->slice->getDepQuantEnabledFlag() && useRegularResidualCoding )
01578   {
01579     //===== scaling matrix ====
01580     const int         qpDQ            = cQP.Qp(tu.mtsIdx[compID] == MTS_SKIP) + 1;
01581     const int         qpPer           = qpDQ / 6;
01582     const int         qpRem           = qpDQ - 6 * qpPer;
01583     const CompArea    &rect           = tu.blocks[compID];
01584     const int         width           = rect.width;
01585     const int         height          = rect.height;
01586     uint32_t          scalingListType = getScalingListType(tu.cu->predMode, compID);
01587     CHECK(scalingListType >= SCALING_LIST_NUM, "Invalid scaling list");
01588     const uint32_t    log2TrWidth     = floorLog2(width);
01589     const uint32_t    log2TrHeight    = floorLog2(height);
01590 
01591     const bool        disableSMForLFNST = tu.cs->slice->getExplicitScalingListUsed() ? tu.cs->slice->getSPS()->getDisableScalingMatrixForLfnstBlks() : false;
01592     const bool        isLfnstApplied = tu.cu->lfnstIdx > 0 && (tu.cu->isSepTree() ? true : isLuma(compID));
01593     const bool        disableSMForACT = tu.cs->slice->getSPS()->getScalingMatrixForAlternativeColourSpaceDisabledFlag() && (tu.cs->slice->getSPS()->getScalingMatrixDesignatedColourSpaceFlag() == tu.cu->colorTransform);
01594     const bool        enableScalingLists = getUseScalingList(width, height, (tu.mtsIdx[compID] == MTS_SKIP), isLfnstApplied, disableSMForLFNST, disableSMForACT);
01595     static_cast<DQIntern::DepQuant*>(p)->quant( tu, pSrc, compID, cQP, Quant::m_dLambda, ctx, uiAbsSum, enableScalingLists, Quant::getQuantCoeff(scalingListType, qpRem, log2TrWidth, log2TrHeight) );
01596   }
01597   else
01598   {
01599     QuantRDOQ::quant( tu, compID, pSrc, uiAbsSum, cQP, ctx );
01600   }
01601 }
01602 
01603 void DepQuant::dequant( const TransformUnit &tu, CoeffBuf &dstCoeff, const ComponentID &compID, const QpParam &cQP )
01604 {
01605   const bool useRegularResidualCoding = tu.cu->slice->getTSResidualCodingDisabledFlag() || tu.mtsIdx[compID] != MTS_SKIP;
01606   if( tu.cs->slice->getDepQuantEnabledFlag() && useRegularResidualCoding )
01607   {
01608     const int         qpDQ            = cQP.Qp(tu.mtsIdx[compID] == MTS_SKIP) + 1;
01609     const int         qpPer           = qpDQ / 6;
01610     const int         qpRem           = qpDQ - 6 * qpPer;
01611     const CompArea    &rect           = tu.blocks[compID];
01612     const int         width           = rect.width;
01613     const int         height          = rect.height;
01614     uint32_t          scalingListType = getScalingListType(tu.cu->predMode, compID);
01615     CHECK(scalingListType >= SCALING_LIST_NUM, "Invalid scaling list");
01616     const uint32_t    log2TrWidth  = floorLog2(width);
01617     const uint32_t    log2TrHeight = floorLog2(height);
01618 
01619     const bool disableSMForLFNST = tu.cs->slice->getExplicitScalingListUsed() ? tu.cs->slice->getSPS()->getDisableScalingMatrixForLfnstBlks() : false;
01620     const bool isLfnstApplied = tu.cu->lfnstIdx > 0 && (tu.cu->isSepTree() ? true : isLuma(compID));
01621     const bool disableSMForACT = tu.cs->slice->getSPS()->getScalingMatrixForAlternativeColourSpaceDisabledFlag() && (tu.cs->slice->getSPS()->getScalingMatrixDesignatedColourSpaceFlag() == tu.cu->colorTransform);
01622     const bool enableScalingLists = getUseScalingList(width, height, (tu.mtsIdx[compID] == MTS_SKIP), isLfnstApplied, disableSMForLFNST, disableSMForACT);
01623     static_cast<DQIntern::DepQuant*>(p)->dequant( tu, dstCoeff, compID, cQP, enableScalingLists, Quant::getDequantCoeff(scalingListType, qpRem, log2TrWidth, log2TrHeight) );
01624   }
01625   else
01626   {
01627     QuantRDOQ::dequant( tu, dstCoeff, compID, cQP );
01628   }
01629 }
